-- =====================================================================
-- dump.sql — full schema, routines, roles and seed data in one file.
-- Generated by concatenating db/01_schema.sql through db/07_seed.sql in
-- order. For the non-Docker path: mysql -u root -p < db/dump.sql
-- (run as root/admin — 06_roles.sql needs privileges to create users).
-- Regenerate after editing any numbered script:
--   cat db/0[1-7]_*.sql > db/dump.sql
-- =====================================================================

-- =====================================================================
-- 01_schema.sql
-- Manzaneque Limited IT Helpdesk — full schema (13 tables).
-- Referential actions: RESTRICT on reference data, SET NULL on optional
-- assignment, CASCADE on dependent detail rows (see ARCHITECTURE.md §3.2).
-- Idempotent: safe to re-run against an empty or previously-built database.
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS audit_log;
DROP TABLE IF EXISTS call_log;
DROP TABLE IF EXISTS problem;
DROP TABLE IF EXISTS specialist_expertise;
DROP TABLE IF EXISTS helpdesk_staff;
DROP TABLE IF EXISTS problem_type;
DROP TABLE IF EXISTS software_licence;
DROP TABLE IF EXISTS software;
DROP TABLE IF EXISTS equipment;
DROP TABLE IF EXISTS equipment_type;
DROP TABLE IF EXISTS employee;
DROP TABLE IF EXISTS job_title;
DROP TABLE IF EXISTS department;

SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------
-- 1. department — reference table for organisational departments.
-- ---------------------------------------------------------------------
CREATE TABLE department (
    department_id   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    department_name VARCHAR(80) NOT NULL,
    CONSTRAINT uq_department_name UNIQUE (department_name)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 2. job_title — reference table for employee job titles.
-- ---------------------------------------------------------------------
CREATE TABLE job_title (
    job_title_id   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    title_name     VARCHAR(80) NOT NULL,
    CONSTRAINT uq_job_title_name UNIQUE (title_name)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 3. employee — personnel register; source of the caller lookup.
-- ---------------------------------------------------------------------
CREATE TABLE employee (
    employee_id     INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    first_name      VARCHAR(60) NOT NULL,
    last_name       VARCHAR(60) NOT NULL,
    email           VARCHAR(120) NOT NULL,
    phone_extension VARCHAR(10) NULL,
    department_id   INT UNSIGNED NOT NULL,
    job_title_id    INT UNSIGNED NOT NULL,
    is_active       TINYINT(1) NOT NULL DEFAULT 1,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_employee_email UNIQUE (email),
    CONSTRAINT fk_employee_department FOREIGN KEY (department_id)
        REFERENCES department (department_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_employee_job_title FOREIGN KEY (job_title_id)
        REFERENCES job_title (job_title_id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 4. equipment_type — reference table (laptop, monitor, printer, ...).
-- ---------------------------------------------------------------------
CREATE TABLE equipment_type (
    equipment_type_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    type_name          VARCHAR(80) NOT NULL,
    CONSTRAINT uq_equipment_type_name UNIQUE (type_name)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 5. equipment — serial-numbered assets, optionally assigned to staff.
-- ---------------------------------------------------------------------
CREATE TABLE equipment (
    equipment_id       INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    serial_number      VARCHAR(60) NOT NULL,
    equipment_type_id  INT UNSIGNED NOT NULL,
    make               VARCHAR(80) NOT NULL,
    model              VARCHAR(80) NOT NULL,
    purchase_date      DATE NULL,
    assigned_employee_id INT UNSIGNED NULL,
    is_retired         TINYINT(1) NOT NULL DEFAULT 0,
    CONSTRAINT uq_equipment_serial UNIQUE (serial_number),
    CONSTRAINT fk_equipment_type FOREIGN KEY (equipment_type_id)
        REFERENCES equipment_type (equipment_type_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_equipment_assigned_employee FOREIGN KEY (assigned_employee_id)
        REFERENCES employee (employee_id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 6. software — software product catalogue.
-- ---------------------------------------------------------------------
CREATE TABLE software (
    software_id    INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    software_name  VARCHAR(100) NOT NULL,
    vendor         VARCHAR(100) NULL,
    CONSTRAINT uq_software_name UNIQUE (software_name)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 7. software_licence — one licence record per equipment/software pair,
--    with a bounded validity window.
-- ---------------------------------------------------------------------
CREATE TABLE software_licence (
    licence_id        INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    equipment_id      INT UNSIGNED NOT NULL,
    software_id       INT UNSIGNED NOT NULL,
    licence_key       VARCHAR(120) NOT NULL,
    licence_start_date DATE NOT NULL,
    licence_end_date   DATE NOT NULL,
    CONSTRAINT fk_licence_equipment FOREIGN KEY (equipment_id)
        REFERENCES equipment (equipment_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_licence_software FOREIGN KEY (software_id)
        REFERENCES software (software_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT chk_licence_dates CHECK (licence_end_date > licence_start_date)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 8. problem_type — self-referencing hierarchy, general -> specific.
--    parent_type_id NULL marks a top-level (most general) type.
-- ---------------------------------------------------------------------
CREATE TABLE problem_type (
    problem_type_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    type_name        VARCHAR(100) NOT NULL,
    parent_type_id   INT UNSIGNED NULL,
    CONSTRAINT uq_problem_type_name UNIQUE (type_name),
    CONSTRAINT fk_problem_type_parent FOREIGN KEY (parent_type_id)
        REFERENCES problem_type (problem_type_id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 9. helpdesk_staff — 1:1 optional extension of employee; holds
--    credentials and the application role.
-- ---------------------------------------------------------------------
CREATE TABLE helpdesk_staff (
    staff_id       INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    employee_id    INT UNSIGNED NOT NULL,
    username       VARCHAR(60) NOT NULL,
    password_hash  VARCHAR(255) NOT NULL,
    staff_role     ENUM('OPERATOR', 'SPECIALIST', 'ANALYST', 'ADMIN') NOT NULL,
    is_active      TINYINT(1) NOT NULL DEFAULT 1,
    created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_helpdesk_staff_employee UNIQUE (employee_id),
    CONSTRAINT uq_helpdesk_staff_username UNIQUE (username),
    CONSTRAINT fk_helpdesk_staff_employee FOREIGN KEY (employee_id)
        REFERENCES employee (employee_id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 10. specialist_expertise — junction: staff <-> problem_type (M:N).
-- ---------------------------------------------------------------------
CREATE TABLE specialist_expertise (
    staff_id        INT UNSIGNED NOT NULL,
    problem_type_id INT UNSIGNED NOT NULL,
    PRIMARY KEY (staff_id, problem_type_id),
    CONSTRAINT fk_expertise_staff FOREIGN KEY (staff_id)
        REFERENCES helpdesk_staff (staff_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_expertise_problem_type FOREIGN KEY (problem_type_id)
        REFERENCES problem_type (problem_type_id) ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 11. problem — the helpdesk ticket. problem_id doubles as the problem
--    number quoted back to the caller (displayed as PR-{id:06d}).
-- ---------------------------------------------------------------------
CREATE TABLE problem (
    problem_id        INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    caller_employee_id INT UNSIGNED NOT NULL,
    equipment_id       INT UNSIGNED NOT NULL,
    problem_type_id    INT UNSIGNED NOT NULL,
    status             ENUM('OPEN', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED', 'CLOSED')
                        NOT NULL DEFAULT 'OPEN',
    priority           ENUM('LOW', 'MEDIUM', 'HIGH', 'CRITICAL') NOT NULL DEFAULT 'MEDIUM',
    assigned_staff_id  INT UNSIGNED NULL,
    logged_by_staff_id INT UNSIGNED NOT NULL,
    logged_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at        DATETIME NULL,
    resolution_notes   TEXT NULL,
    minutes_to_resolve INT UNSIGNED NULL,
    CONSTRAINT fk_problem_caller FOREIGN KEY (caller_employee_id)
        REFERENCES employee (employee_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_problem_equipment FOREIGN KEY (equipment_id)
        REFERENCES equipment (equipment_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_problem_type FOREIGN KEY (problem_type_id)
        REFERENCES problem_type (problem_type_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_problem_assigned_staff FOREIGN KEY (assigned_staff_id)
        REFERENCES helpdesk_staff (staff_id) ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_problem_logged_by FOREIGN KEY (logged_by_staff_id)
        REFERENCES helpdesk_staff (staff_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT chk_problem_resolved_after_logged
        CHECK (resolved_at IS NULL OR resolved_at >= logged_at)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 12. call_log — many calls per problem: the initial report plus any
--    follow-up calls from the caller or specialist notes.
-- ---------------------------------------------------------------------
CREATE TABLE call_log (
    call_log_id    INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    problem_id     INT UNSIGNED NOT NULL,
    staff_id       INT UNSIGNED NOT NULL,
    call_type      ENUM('INITIAL', 'FOLLOW_UP') NOT NULL,
    notes          TEXT NOT NULL,
    logged_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_call_log_problem FOREIGN KEY (problem_id)
        REFERENCES problem (problem_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_call_log_staff FOREIGN KEY (staff_id)
        REFERENCES helpdesk_staff (staff_id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 13. audit_log — trigger-populated change history for problem rows.
--    Justified under M2 system security (traceability of who changed what).
-- ---------------------------------------------------------------------
CREATE TABLE audit_log (
    audit_log_id   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    problem_id     INT UNSIGNED NOT NULL,
    changed_field  VARCHAR(40) NOT NULL,
    old_value      VARCHAR(255) NULL,
    new_value      VARCHAR(255) NULL,
    changed_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_audit_log_problem FOREIGN KEY (problem_id)
        REFERENCES problem (problem_id) ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB;
-- =====================================================================
-- 02_indexes.sql
-- Indexes beyond those InnoDB creates automatically for PRIMARY KEY and
-- UNIQUE constraints. Every FK column gets one (MySQL does not add these
-- automatically the way it does for the referencing side of a FK on some
-- engines — InnoDB does index FK columns automatically, but we index the
-- composite/report-filter columns explicitly and document why).
-- Run once against tables freshly created by 01_schema.sql. Since that
-- script drops and recreates every table, re-running 01 then 02 in
-- sequence is safe; running 02 alone a second time is not (MySQL 8.0
-- has no CREATE INDEX IF NOT EXISTS), so it is not intended to be re-run
-- in isolation.
-- =====================================================================

-- employee.department_id / job_title_id are already indexed by InnoDB as
-- the FK columns; no additional index needed for lookups by department
-- alone, since department listings are small reference-table scans.

-- ---------------------------------------------------------------------
-- equipment: report and lookup filters.
-- ---------------------------------------------------------------------
-- Serial lookup (Log a Call screen) is already covered by the UNIQUE
-- constraint on serial_number. Equipment failure ranking groups by type.
CREATE INDEX idx_equipment_type ON equipment (equipment_type_id);

-- ---------------------------------------------------------------------
-- software_licence: licence validity is checked per equipment on every
-- serial lookup, and expiry reporting filters/sorts by end date.
-- ---------------------------------------------------------------------
CREATE INDEX idx_licence_equipment ON software_licence (equipment_id);
CREATE INDEX idx_licence_end_date ON software_licence (licence_end_date);

-- ---------------------------------------------------------------------
-- problem_type: the recursive hierarchy walk in fn_find_specialist joins
-- repeatedly on parent_type_id.
-- ---------------------------------------------------------------------
CREATE INDEX idx_problem_type_parent ON problem_type (parent_type_id);

-- ---------------------------------------------------------------------
-- specialist_expertise: fn_find_specialist and sp_assign_least_loaded
-- both look up "which staff cover problem_type X" — the PK already
-- covers (staff_id, problem_type_id); add the reverse order for lookups
-- keyed by problem_type_id first.
-- ---------------------------------------------------------------------
CREATE INDEX idx_expertise_problem_type ON specialist_expertise (problem_type_id);

-- ---------------------------------------------------------------------
-- problem: this is the table every report and the Problem List screen
-- filters, sorts and joins on. Cover the filterable/sortable columns
-- individually and the hot composite used for workload counting.
-- ---------------------------------------------------------------------
CREATE INDEX idx_problem_caller ON problem (caller_employee_id);
CREATE INDEX idx_problem_equipment ON problem (equipment_id);
CREATE INDEX idx_problem_type ON problem (problem_type_id);
CREATE INDEX idx_problem_status ON problem (status);
CREATE INDEX idx_problem_assigned_staff ON problem (assigned_staff_id);
CREATE INDEX idx_problem_logged_by ON problem (logged_by_staff_id);
-- Problem List default sort is newest-first; open-by-age report filters
-- on status then orders by logged_at.
CREATE INDEX idx_problem_status_logged_at ON problem (status, logged_at);
-- sp_assign_least_loaded counts each specialist's currently-open problems
-- — this composite lets that COUNT ... GROUP BY use an index range scan
-- instead of a full table scan as problem volume grows.
CREATE INDEX idx_problem_assigned_status ON problem (assigned_staff_id, status);

-- ---------------------------------------------------------------------
-- call_log: problem detail screen loads full call history per problem,
-- ordered chronologically.
-- ---------------------------------------------------------------------
CREATE INDEX idx_call_log_problem ON call_log (problem_id, logged_at);
CREATE INDEX idx_call_log_staff ON call_log (staff_id);

-- ---------------------------------------------------------------------
-- audit_log: evidence/reporting lookups by problem.
-- ---------------------------------------------------------------------
CREATE INDEX idx_audit_log_problem ON audit_log (problem_id, changed_at);

-- ---------------------------------------------------------------------
-- helpdesk_staff: login is by username (already UNIQUE -> indexed);
-- role filter used by RBAC-adjacent admin listings.
-- ---------------------------------------------------------------------
CREATE INDEX idx_helpdesk_staff_role ON helpdesk_staff (staff_role);
-- =====================================================================
-- 03_views.sql
-- Four management-information views (M3). Each answers one question the
-- brief asks; aggregation lives here, not in application code.
-- =====================================================================

DROP VIEW IF EXISTS vw_open_problems_by_age;
DROP VIEW IF EXISTS vw_specialist_workload;
DROP VIEW IF EXISTS vw_equipment_failure_ranking;
DROP VIEW IF EXISTS vw_problem_type_frequency;

-- ---------------------------------------------------------------------
-- vw_open_problems_by_age
-- Question: what is outstanding, and for how long?
-- Every problem not yet RESOLVED/CLOSED, with its age in hours and the
-- caller/equipment/type/assignee context needed to triage it.
-- ---------------------------------------------------------------------
CREATE VIEW vw_open_problems_by_age AS
SELECT
    p.problem_id,
    p.status,
    p.priority,
    p.logged_at,
    TIMESTAMPDIFF(HOUR, p.logged_at, NOW()) AS age_hours,
    CONCAT(e.first_name, ' ', e.last_name) AS caller_name,
    d.department_name,
    eq.serial_number,
    et.type_name AS equipment_type_name,
    pt.type_name AS problem_type_name,
    p.assigned_staff_id,
    CONCAT(se.first_name, ' ', se.last_name) AS assigned_staff_name
FROM problem p
JOIN employee e        ON e.employee_id = p.caller_employee_id
JOIN department d       ON d.department_id = e.department_id
JOIN equipment eq       ON eq.equipment_id = p.equipment_id
JOIN equipment_type et  ON et.equipment_type_id = eq.equipment_type_id
JOIN problem_type pt    ON pt.problem_type_id = p.problem_type_id
LEFT JOIN helpdesk_staff hs ON hs.staff_id = p.assigned_staff_id
LEFT JOIN employee se       ON se.employee_id = hs.employee_id
WHERE p.status IN ('OPEN', 'ASSIGNED', 'IN_PROGRESS');

-- ---------------------------------------------------------------------
-- vw_specialist_workload
-- Question: are specialists sufficiently resourced?
-- Per specialist: how many problems currently open, how many resolved
-- historically, and their average resolution time in minutes.
-- ---------------------------------------------------------------------
CREATE VIEW vw_specialist_workload AS
SELECT
    hs.staff_id,
    CONCAT(e.first_name, ' ', e.last_name) AS specialist_name,
    COUNT(CASE WHEN p.status IN ('ASSIGNED', 'IN_PROGRESS') THEN 1 END) AS open_problem_count,
    COUNT(CASE WHEN p.status IN ('RESOLVED', 'CLOSED') THEN 1 END) AS resolved_problem_count,
    ROUND(AVG(CASE WHEN p.status IN ('RESOLVED', 'CLOSED') THEN p.minutes_to_resolve END), 1)
        AS avg_minutes_to_resolve
FROM helpdesk_staff hs
JOIN employee e ON e.employee_id = hs.employee_id
LEFT JOIN problem p ON p.assigned_staff_id = hs.staff_id
WHERE hs.staff_role = 'SPECIALIST'
GROUP BY hs.staff_id, e.first_name, e.last_name;

-- ---------------------------------------------------------------------
-- vw_equipment_failure_ranking
-- Question: how is the equipment performing overall?
-- Per equipment item: how many problems have been logged against it and
-- how recently, ranked worst-first.
-- ---------------------------------------------------------------------
CREATE VIEW vw_equipment_failure_ranking AS
SELECT
    eq.equipment_id,
    eq.serial_number,
    et.type_name AS equipment_type_name,
    eq.make,
    eq.model,
    COUNT(p.problem_id) AS problem_count,
    MAX(p.logged_at) AS last_problem_logged_at
FROM equipment eq
JOIN equipment_type et ON et.equipment_type_id = eq.equipment_type_id
LEFT JOIN problem p ON p.equipment_id = eq.equipment_id
GROUP BY eq.equipment_id, eq.serial_number, et.type_name, eq.make, eq.model
ORDER BY problem_count DESC;

-- ---------------------------------------------------------------------
-- vw_problem_type_frequency
-- Question: where is employee training needed?
-- Rolls specific problem types up to their top-level parent so frequency
-- is meaningful even when specialists log against fine-grained subtypes.
-- ---------------------------------------------------------------------
CREATE VIEW vw_problem_type_frequency AS
WITH RECURSIVE type_root (problem_type_id, root_type_id) AS (
    SELECT problem_type_id, problem_type_id
    FROM problem_type
    WHERE parent_type_id IS NULL
    UNION ALL
    SELECT pt.problem_type_id, tr.root_type_id
    FROM problem_type pt
    JOIN type_root tr ON pt.parent_type_id = tr.problem_type_id
)
SELECT
    root.root_type_id,
    root_pt.type_name AS root_type_name,
    COUNT(p.problem_id) AS problem_count
FROM type_root root
JOIN problem_type root_pt ON root_pt.problem_type_id = root.root_type_id
LEFT JOIN problem p ON p.problem_type_id = root.problem_type_id
GROUP BY root.root_type_id, root_pt.type_name
ORDER BY problem_count DESC;
-- =====================================================================
-- 04_procedures.sql
-- Three procedures + one function. Multi-step operations run as
-- transactions here so the API layer never has to coordinate writes.
-- =====================================================================

DROP PROCEDURE IF EXISTS sp_log_new_call;
DROP PROCEDURE IF EXISTS sp_assign_least_loaded;
DROP PROCEDURE IF EXISTS sp_resolve_problem;
DROP FUNCTION IF EXISTS fn_find_specialist;

DELIMITER $$

-- ---------------------------------------------------------------------
-- fn_find_specialist(problem_type_id)
-- Brief: "If there is no specialist listed for a more specific problem
-- type, then a specialist from the more general problem type will be
-- used." Walks parent_type_id upward from the given type until it finds
-- a type with at least one qualified specialist, and returns that
-- type's id. Returns NULL if no ancestor (or the type itself) has one.
-- ---------------------------------------------------------------------
CREATE FUNCTION fn_find_specialist(p_problem_type_id INT UNSIGNED)
RETURNS INT UNSIGNED
DETERMINISTIC
READS SQL DATA
BEGIN
    DECLARE v_result_type_id INT UNSIGNED DEFAULT NULL;

    WITH RECURSIVE type_chain (problem_type_id, parent_type_id, depth) AS (
        SELECT problem_type_id, parent_type_id, 0
        FROM problem_type
        WHERE problem_type_id = p_problem_type_id
        UNION ALL
        SELECT pt.problem_type_id, pt.parent_type_id, tc.depth + 1
        FROM problem_type pt
        JOIN type_chain tc ON pt.problem_type_id = tc.parent_type_id
    )
    SELECT tc.problem_type_id INTO v_result_type_id
    FROM type_chain tc
    WHERE EXISTS (
        SELECT 1
        FROM specialist_expertise se
        JOIN helpdesk_staff hs ON hs.staff_id = se.staff_id
        WHERE se.problem_type_id = tc.problem_type_id
          AND hs.staff_role = 'SPECIALIST'
          AND hs.is_active = 1
    )
    ORDER BY tc.depth ASC
    LIMIT 1;

    RETURN v_result_type_id;
END$$

-- ---------------------------------------------------------------------
-- sp_log_new_call(caller, equipment, problem_type, priority, notes,
--                  logging staff, OUT problem_id, OUT problem_number)
-- Transaction: creates a new problem plus its initial call_log row, and
-- returns the problem number to quote back to the caller. Used only for
-- the *first* call on a problem — follow-up calls insert directly into
-- call_log via the API layer since they do not create new state.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_log_new_call (
    IN  p_caller_employee_id INT UNSIGNED,
    IN  p_equipment_id       INT UNSIGNED,
    IN  p_problem_type_id    INT UNSIGNED,
    IN  p_priority           VARCHAR(10),
    IN  p_notes              TEXT,
    IN  p_logged_by_staff_id INT UNSIGNED,
    OUT p_problem_id         INT UNSIGNED,
    OUT p_problem_number     VARCHAR(16)
)
proc: BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

        caller_employee_id, equipment_id, problem_type_id,
        status, priority, logged_by_staff_id
    ) VALUES (
        p_caller_employee_id, p_equipment_id, p_problem_type_id,
        'OPEN', p_priority, p_logged_by_staff_id
    );

    SET p_problem_id = LAST_INSERT_ID();

    VALUES (p_problem_id, p_logged_by_staff_id, 'INITIAL', p_notes);

    SET p_problem_number = CONCAT('PR-', LPAD(p_problem_id, 6, '0'));

    COMMIT;
END$$

-- ---------------------------------------------------------------------
-- sp_assign_least_loaded(problem_id, OUT assigned_staff_id)
-- Brief: "the specialist who is currently the least loaded can be
-- allocated." Finds the specialist pool via fn_find_specialist (walking
-- the hierarchy on fallback), then picks the one with the fewest
-- currently-open (ASSIGNED/IN_PROGRESS) problems; ties broken by whoever
-- was assigned longest ago (earliest last assignment), so workload
-- keeps rotating rather than always landing on the same tied specialist.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_assign_least_loaded (
    IN  p_problem_id        INT UNSIGNED,
    OUT p_assigned_staff_id INT UNSIGNED
)
proc: BEGIN
    DECLARE v_problem_type_id  INT UNSIGNED;
    DECLARE v_resolved_type_id INT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    SELECT problem_type_id INTO v_problem_type_id
    FROM problem
    WHERE problem_id = p_problem_id
    FOR UPDATE;

    SET v_resolved_type_id = fn_find_specialist(v_problem_type_id);

    IF v_resolved_type_id IS NULL THEN
        SET p_assigned_staff_id = NULL;
        ROLLBACK;
        LEAVE proc;
    END IF;

    SELECT hs.staff_id INTO p_assigned_staff_id
    FROM helpdesk_staff hs
    JOIN specialist_expertise se ON se.staff_id = hs.staff_id
    LEFT JOIN (
        SELECT assigned_staff_id, COUNT(*) AS open_count, MAX(logged_at) AS last_assigned_at
        FROM problem
        WHERE status IN ('ASSIGNED', 'IN_PROGRESS')
        GROUP BY assigned_staff_id
    ) load_summary ON load_summary.assigned_staff_id = hs.staff_id
    WHERE se.problem_type_id = v_resolved_type_id
      AND hs.staff_role = 'SPECIALIST'
      AND hs.is_active = 1
    ORDER BY
        COALESCE(load_summary.open_count, 0) ASC,
        COALESCE(load_summary.last_assigned_at, '1970-01-01') ASC
    LIMIT 1;

    UPDATE problem
    SET assigned_staff_id = p_assigned_staff_id,
        status = 'ASSIGNED'
    WHERE problem_id = p_problem_id;

    COMMIT;
END$$

-- ---------------------------------------------------------------------
-- sp_resolve_problem(problem_id, resolution_notes, resolving staff)
-- Sets resolved_at, stores the resolution notes and transitions status
-- to RESOLVED. minutes_to_resolve is derived by trg_problem_before_update
-- on the same UPDATE, not computed here.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_resolve_problem (
    IN p_problem_id       INT UNSIGNED,
    IN p_resolution_notes TEXT,
    IN p_resolved_by_staff_id INT UNSIGNED
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    UPDATE problem
    SET status = 'RESOLVED',
        resolved_at = NOW(),
        resolution_notes = p_resolution_notes
    WHERE problem_id = p_problem_id;

    VALUES (p_problem_id, p_resolved_by_staff_id, 'FOLLOW_UP',
            CONCAT('Resolved: ', p_resolution_notes));

    COMMIT;
END$$

DELIMITER ;
-- =====================================================================
-- 05_triggers.sql
-- Two triggers on problem, both fired by any UPDATE — one derives a
-- value before the row is written, the other records history after.
-- =====================================================================

DROP TRIGGER IF EXISTS trg_problem_before_update;
DROP TRIGGER IF EXISTS trg_problem_after_update;

DELIMITER $$

-- ---------------------------------------------------------------------
-- trg_problem_before_update
-- Derives minutes_to_resolve the moment resolved_at is set (and was not
-- already set), so the value is never computed or trusted from the app.
-- ---------------------------------------------------------------------
CREATE TRIGGER trg_problem_before_update
BEFORE UPDATE ON problem
FOR EACH ROW
BEGIN
    IF NEW.resolved_at IS NOT NULL AND OLD.resolved_at IS NULL THEN
        SET NEW.minutes_to_resolve = TIMESTAMPDIFF(MINUTE, NEW.logged_at, NEW.resolved_at);
    END IF;
END$$

-- ---------------------------------------------------------------------
-- trg_problem_after_update
-- Audit row on any status, type or assignment change — the fields that
-- represent the lifecycle of the ticket. Justified under M2 security as
-- traceability of who/what changed a problem, and when.
-- ---------------------------------------------------------------------
CREATE TRIGGER trg_problem_after_update
AFTER UPDATE ON problem
FOR EACH ROW
BEGIN
    IF NOT (NEW.status <=> OLD.status) THEN
        VALUES (NEW.problem_id, 'status', OLD.status, NEW.status);
    END IF;

    IF NOT (NEW.problem_type_id <=> OLD.problem_type_id) THEN
        VALUES (NEW.problem_id, 'problem_type_id', OLD.problem_type_id, NEW.problem_type_id);
    END IF;

    IF NOT (NEW.assigned_staff_id <=> OLD.assigned_staff_id) THEN
        VALUES (NEW.problem_id, 'assigned_staff_id', OLD.assigned_staff_id, NEW.assigned_staff_id);
    END IF;
END$$

DELIMITER ;
-- =====================================================================
-- 06_roles.sql
-- Four least-privilege MySQL roles (M2 security) plus the restricted
-- application user, which is granted every role and connects as
-- neither root nor any single fixed-privilege account. The app enforces
-- which role's privileges apply per request via its own RBAC middleware
-- — MySQL roles here exist so the *database* also refuses what the API
-- should never have asked for in the first place (defence in depth).
-- Run as root/admin during provisioning only.
-- =====================================================================

DROP USER IF EXISTS 'hd_app'@'%';
DROP ROLE IF EXISTS hd_operator, hd_specialist, hd_analyst, hd_admin;

CREATE ROLE hd_operator, hd_specialist, hd_analyst, hd_admin;

-- ---------------------------------------------------------------------
-- hd_operator — logs calls, looks up callers/equipment/knowledge base,
-- tracks problems in their own queue. Cannot resolve, assign, or touch
-- reference/admin data.
-- ---------------------------------------------------------------------
GRANT SELECT ON manzaneque_helpdesk.employee            TO hd_operator;
GRANT SELECT ON manzaneque_helpdesk.department           TO hd_operator;
GRANT SELECT ON manzaneque_helpdesk.job_title            TO hd_operator;
GRANT SELECT ON manzaneque_helpdesk.equipment            TO hd_operator;
GRANT SELECT ON manzaneque_helpdesk.equipment_type       TO hd_operator;
GRANT SELECT ON manzaneque_helpdesk.software_licence     TO hd_operator;
GRANT SELECT ON manzaneque_helpdesk.software             TO hd_operator;
GRANT SELECT ON manzaneque_helpdesk.problem_type         TO hd_operator;
GRANT SELECT, INSERT ON manzaneque_helpdesk.problem      TO hd_operator;
GRANT SELECT, INSERT ON manzaneque_helpdesk.call_log     TO hd_operator;
GRANT EXECUTE ON PROCEDURE manzaneque_helpdesk.sp_log_new_call TO hd_operator;
GRANT EXECUTE ON PROCEDURE manzaneque_helpdesk.sp_assign_least_loaded TO hd_operator;
GRANT EXECUTE ON FUNCTION manzaneque_helpdesk.fn_find_specialist TO hd_operator;

-- ---------------------------------------------------------------------
-- hd_specialist — works their assigned queue: reclassify, add follow-up
-- calls, resolve. No access to reference-data maintenance or reports.
-- ---------------------------------------------------------------------
GRANT SELECT ON manzaneque_helpdesk.employee            TO hd_specialist;
GRANT SELECT ON manzaneque_helpdesk.department           TO hd_specialist;
GRANT SELECT ON manzaneque_helpdesk.equipment            TO hd_specialist;
GRANT SELECT ON manzaneque_helpdesk.equipment_type       TO hd_specialist;
GRANT SELECT ON manzaneque_helpdesk.software_licence     TO hd_specialist;
GRANT SELECT ON manzaneque_helpdesk.software             TO hd_specialist;
GRANT SELECT ON manzaneque_helpdesk.problem_type         TO hd_specialist;
GRANT SELECT ON manzaneque_helpdesk.specialist_expertise TO hd_specialist;
GRANT SELECT, UPDATE ON manzaneque_helpdesk.problem      TO hd_specialist;
GRANT SELECT, INSERT ON manzaneque_helpdesk.call_log     TO hd_specialist;
GRANT SELECT ON manzaneque_helpdesk.audit_log            TO hd_specialist;
GRANT EXECUTE ON PROCEDURE manzaneque_helpdesk.sp_resolve_problem TO hd_specialist;
GRANT EXECUTE ON PROCEDURE manzaneque_helpdesk.sp_assign_least_loaded TO hd_specialist;
GRANT EXECUTE ON FUNCTION manzaneque_helpdesk.fn_find_specialist TO hd_specialist;

-- ---------------------------------------------------------------------
-- hd_analyst — read-only across the reporting views and their source
-- tables. No writes anywhere.
-- ---------------------------------------------------------------------
GRANT SELECT ON manzaneque_helpdesk.vw_open_problems_by_age      TO hd_analyst;
GRANT SELECT ON manzaneque_helpdesk.vw_specialist_workload        TO hd_analyst;
GRANT SELECT ON manzaneque_helpdesk.vw_equipment_failure_ranking  TO hd_analyst;
GRANT SELECT ON manzaneque_helpdesk.vw_problem_type_frequency     TO hd_analyst;
GRANT SELECT ON manzaneque_helpdesk.problem              TO hd_analyst;
GRANT SELECT ON manzaneque_helpdesk.employee             TO hd_analyst;
GRANT SELECT ON manzaneque_helpdesk.equipment            TO hd_analyst;
GRANT SELECT ON manzaneque_helpdesk.equipment_type       TO hd_analyst;
GRANT SELECT ON manzaneque_helpdesk.problem_type         TO hd_analyst;
GRANT SELECT ON manzaneque_helpdesk.helpdesk_staff       TO hd_analyst;

-- ---------------------------------------------------------------------
-- hd_admin — full CRUD on the reference data the app exposes admin
-- screens for (employees, equipment, problem types), plus everything
-- the other roles can do, for support purposes. No DDL.
-- ---------------------------------------------------------------------
GRANT hd_operator, hd_specialist, hd_analyst TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.employee       TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.equipment      TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.problem_type   TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.department     TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.job_title      TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.equipment_type TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.software       TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.software_licence TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.helpdesk_staff TO hd_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON manzaneque_helpdesk.specialist_expertise TO hd_admin;

-- ---------------------------------------------------------------------
-- Restricted application user. The Express app authenticates to MySQL
-- as this single user and holds every role; the app's own RBAC
-- middleware (server/src/middleware) decides which role's privileges a
-- given JWT is allowed to exercise. Never used interactively, never
-- granted directly to a person.
--
-- The password below MUST match DB_APP_PASSWORD in your .env. If you
-- change one, change the other (see README) — this script only runs
-- automatically on first container init, so a later .env edit alone
-- will not update it; re-run this file's CREATE/ALTER USER by hand.
-- ---------------------------------------------------------------------
CREATE USER 'hd_app'@'%' IDENTIFIED BY 'change_me_app';
GRANT hd_operator, hd_specialist, hd_analyst, hd_admin TO 'hd_app'@'%';
SET DEFAULT ROLE ALL TO 'hd_app'@'%';

FLUSH PRIVILEGES;
